package com.lmspilot.enrollment.api;
import com.lmspilot.enrollment.domain.*; import com.lmspilot.enrollment.platform.CourseAssignmentPolicy; import com.lmspilot.support.api.ApiException; import com.lmspilot.support.security.CurrentUser; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.*; import java.util.*; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
record CreateCourseAssignmentRequest(@NotNull UUID courseId,@NotNull AssignmentTargetType assigneeType,@NotNull UUID assigneeId,Integer assignedVersion,Instant availableFrom,Instant dueAt,Integer gracePeriodMinutes,Boolean required){} record CourseAssignmentResponse(UUID id,UUID courseId,AssignmentTargetType assigneeType,UUID assigneeId,int assignedVersion,Instant availableFrom,Instant dueAt,int gracePeriodMinutes,boolean required,CourseAssignmentStatus status,Instant assignedAt){} record CreateLiveSessionRequest(@NotNull UUID courseId,@NotBlank String title,String provider,@NotBlank String joinUrl,String hostUrl,@NotNull Instant startsAt,@NotNull Instant endsAt){} record LiveSessionResponse(UUID id,UUID courseId,String title,String provider,String joinUrl,String hostUrl,Instant startsAt,Instant endsAt,LiveSessionStatus status){}
@Service @Transactional class AssignmentLiveService { private final CourseAssignmentRepository assignments;private final EnrollmentRepository enrollments;private final LiveSessionRepository live;AssignmentLiveService(CourseAssignmentRepository a,EnrollmentRepository e,LiveSessionRepository l){assignments=a;enrollments=e;live=l;} CourseAssignmentResponse assign(CreateCourseAssignmentRequest i){int g=i.gracePeriodMinutes()==null?0:i.gracePeriodMinutes();CourseAssignmentPolicy.validate(i.assigneeType(),i.assigneeId(),i.availableFrom(),i.dueAt(),g);CourseAssignmentEntity a=new CourseAssignmentEntity();a.courseId=i.courseId();a.classId=i.courseId();a.assigneeType=i.assigneeType();a.assigneeId=i.assigneeId();a.assignedVersion=i.assignedVersion()==null?1:i.assignedVersion();a.availableFrom=i.availableFrom();a.dueAt=i.dueAt();a.gracePeriodMinutes=g;a.required=i.required()==null||i.required();a.assignedBy=user();assignments.save(a);if(i.assigneeType()==AssignmentTargetType.USER){EnrollmentEntity e=new EnrollmentEntity();e.classId=i.courseId();e.courseId=i.courseId();e.userId=i.assigneeId();e.dueAt=i.dueAt();e.idempotencyKey="assignment:"+a.id;enrollments.save(e);}return view(a);} List<CourseAssignmentResponse> courseAssignments(UUID id){return assignments.findAllByCourseIdOrderByAssignedAtDesc(id).stream().map(this::view).toList();} List<CourseAssignmentResponse> mine(){return assignments.findAllByAssigneeTypeAndAssigneeIdAndStatusOrderByAssignedAtDesc(AssignmentTargetType.USER,user(),CourseAssignmentStatus.ACTIVE).stream().map(this::view).toList();} void revoke(UUID id){CourseAssignmentEntity a=assignments.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"ASSIGNMENT_NOT_FOUND","Không tìm thấy phân công"));a.status=CourseAssignmentStatus.CANCELLED;assignments.save(a);} LiveSessionResponse createLive(CreateLiveSessionRequest i){if(!i.endsAt().isAfter(i.startsAt()))throw new ApiException(HttpStatus.BAD_REQUEST,"LIVE_TIME_INVALID","Thời gian kết thúc phải sau thời gian bắt đầu");LiveSessionEntity e=new LiveSessionEntity();e.classId=i.courseId();e.courseId=i.courseId();e.title=i.title().trim();e.provider=i.provider()==null?"EXTERNAL":i.provider();e.joinUrl=i.joinUrl();e.hostUrl=i.hostUrl();e.startsAt=i.startsAt();e.endsAt=i.endsAt();e.createdBy=user();live.save(e);return live(e);} List<LiveSessionResponse> courseLive(UUID c){return live.findAllByCourseIdAndEndsAtAfterOrderByStartsAtAsc(c,Instant.now()).stream().map(this::live).toList();} List<LiveSessionResponse> myLive(){Set<UUID> courses=new HashSet<>();mine().forEach(a->courses.add(a.courseId()));return courses.stream().flatMap(c->courseLive(c).stream()).sorted(Comparator.comparing(LiveSessionResponse::startsAt)).toList();} private CourseAssignmentResponse view(CourseAssignmentEntity a){return new CourseAssignmentResponse(a.id,a.courseId,a.assigneeType,a.assigneeId,a.assignedVersion,a.availableFrom,a.dueAt,a.gracePeriodMinutes,a.required,a.status,a.assignedAt);}private LiveSessionResponse live(LiveSessionEntity e){return new LiveSessionResponse(e.id,e.courseId,e.title,e.provider,e.joinUrl,e.hostUrl,e.startsAt,e.endsAt,e.status);}private UUID user(){try{return CurrentUser.id();}catch(Exception e){return new UUID(0,1);}} }
@RestController @RequestMapping("/api/v1/course-assignments") public class AssignmentAndLiveApi { private final AssignmentLiveService service;public AssignmentAndLiveApi(AssignmentLiveService s){service=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED) public CourseAssignmentResponse assign(@Valid @RequestBody CreateCourseAssignmentRequest i){return service.assign(i);}@GetMapping public List<CourseAssignmentResponse> list(@RequestParam UUID courseId){return service.courseAssignments(courseId);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void revoke(@PathVariable UUID id){service.revoke(id);}@GetMapping("/me") public List<CourseAssignmentResponse> mine(){return service.mine();} }
@RestController @RequestMapping("/api/v1/live-sessions") class LiveSessionController {private final AssignmentLiveService service;LiveSessionController(AssignmentLiveService s){service=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED) LiveSessionResponse create(@Valid @RequestBody CreateLiveSessionRequest i){return service.createLive(i);}@GetMapping("/me") List<LiveSessionResponse> mine(){return service.myLive();}@GetMapping List<LiveSessionResponse> list(@RequestParam UUID courseId){return service.courseLive(courseId);} }
